// La finestra e' di 3 giorni, non di 1, anche se il workflow gira ogni
// giorno: se una esecuzione salta (n8n fermo, TED lento, rete giu') una
// finestra da 24 ore perde quegli avvisi per sempre e nessuno se ne accorge.
// L'upsert a valle rende innocuo rivedere gli stessi avvisi.
const giorni = 3;
const d = new Date(Date.now() - giorni * 86400000);
const dal = d.toISOString().slice(0, 10).replace(/-/g, '');

// CPV a otto cifre: l'API rifiuta i prefissi corti come '72'.
const query = `classification-cpv IN (72000000 48000000) AND buyer-country IN (ITA) AND publication-date >= ${dal}`;

// 'fields' e' obbligatorio e i nomi sono verificati: sbagliarne uno da' 400.
const fields = [
  'publication-number', 'notice-title', 'buyer-name', 'buyer-city',
  'deadline-receipt-tender-date-lot', 'classification-cpv',
  'publication-date', 'notice-type', 'procedure-type', 'contract-nature',
  'estimated-value-lot', 'estimated-value-cur-lot', 'description-lot',
  'links', 'notice-identifier'
];

return [{ json: { query, limit: 100, fields, paginationMode: 'ITERATION' } }];

// TED restituisce quasi ogni campo come dizionario per lingua ({"ita": [...]})
// e quasi ogni campo come lista, una voce per lotto. Serve appiattire in un
// posto solo: farlo a valle vorrebbe dire venti espressioni fragili.
function testo(v) {
  if (v === null || v === undefined) return null;
  if (Array.isArray(v)) return v.length ? testo(v[0]) : null;
  if (typeof v === 'object') {
    for (const k of ['ita', 'mul', 'eng']) if (k in v) return testo(v[k]);
    const vals = Object.values(v);
    return vals.length ? testo(vals[0]) : null;
  }
  return String(v).trim() || null;
}

function tutte(v) {
  if (v === null || v === undefined) return [];
  if (Array.isArray(v)) return v.flatMap(tutte);
  if (typeof v === 'object') {
    for (const k of ['ita', 'mul', 'eng']) if (k in v) return tutte(v[k]);
    const vals = Object.values(v);
    return vals.length ? tutte(vals[0]) : [];
  }
  const s = String(v).trim();
  return s ? [s] : [];
}

function dataIso(v) {
  const m = /^(\d{4}-\d{2}-\d{2})/.exec(String(v || ''));
  return m ? m[1] : null;
}

const oggi = new Date().toISOString().slice(0, 10);
const avvisi = [];

for (const item of $input.all()) {
  for (const n of (item.json.notices || [])) {
    // La scadenza e' un array: un avviso con otto lotti ha otto date. Serve
    // la piu' vicina fra quelle ancora nel futuro — e' quella che dice entro
    // quando bisogna muoversi.
    const date_ = tutte(n['deadline-receipt-tender-date-lot'])
      .map(dataIso).filter(Boolean).sort();
    const future = date_.filter(d => d >= oggi);
    const scadenza = future.length ? future[0] : (date_.length ? date_[date_.length - 1] : null);

    const valore = tutte(n['estimated-value-lot'])
      .map(x => parseFloat(String(x).replace(',', '.')))
      .filter(x => !isNaN(x))
      .reduce((a, b) => a + b, 0) || null;

    const numero = testo(n['publication-number']);
    if (!numero) continue;

    avvisi.push({
      numero,
      identificativo: testo(n['notice-identifier']),
      titolo: testo(n['notice-title']),
      ente: testo(n['buyer-name']),
      citta: testo(n['buyer-city']),
      pubblicato: dataIso(testo(n['publication-date'])),
      scadenza,
      n_lotti: date_.length,
      cpv: [...new Set(tutte(n['classification-cpv']))].slice(0, 6).join(','),
      tipo: testo(n['notice-type']),
      procedura: testo(n['procedure-type']),
      natura: testo(n['contract-nature']),
      valore,
      valuta: testo(n['estimated-value-cur-lot']),
      oggetto: (testo(n['description-lot']) || '').slice(0, 2000) || null,
      link: ((n.links || {}).xml || {}).MUL || ((n.links || {}).pdf || {}).ITA || null
    });
  }
}

// Un solo item con tutto dentro: la scrittura a valle e' una query sola
// invece di una per avviso. Su cento avvisi sono cento round-trip risparmiati.
return [{ json: { payload: JSON.stringify(avvisi), quanti: avvisi.length } }];

